var a=110;var i=[{id:`cooking-110-01`,theoryId:110,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What is a central function of kneading wheat-based fresh pasta dough?`,ua:`Яка основна роль замішування тіста для свіжої пшеничної пасти?`},explanation:{en:`Kneading distributes moisture and develops gluten structure in wheat dough.`,ua:`Замішування розподіляє вологу й розвиває клейковинну структуру пшеничного тіста.`},options:[{id:`a`,text:{en:`Developing cohesive dough structure`,ua:`Розвиток цілісної структури тіста`}},{id:`b`,text:{en:`Removing all moisture`,ua:`Видалення всієї вологи`}},{id:`c`,text:{en:`Fermenting it into alcohol instantly`,ua:`Миттєве спиртове бродіння`}}],answer:{optionIds:[`a`]}},{id:`cooking-110-02`,theoryId:110,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Resting fresh pasta dough can make it easier to roll thinly.`,ua:`Відпочинок тіста для свіжої пасти може полегшувати його тонке розкачування.`},explanation:{en:`Resting allows hydration to even out and gluten to relax.`,ua:`Під час відпочинку вирівнюється гідратація та розслаблюється клейковина.`},answer:{value:!0}},{id:`cooking-110-03`,theoryId:110,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match pasta-making stages to their goals.`,ua:`Поєднайте етапи виготовлення пасти з цілями.`},explanation:{en:`Each step controls structure and final bite.`,ua:`Кожен етап керує структурою та кінцевою пружністю.`},leftItems:[{id:`l1`,text:{en:`Mix and knead`,ua:`Змішати й замісити`}},{id:`l2`,text:{en:`Rest covered`,ua:`Дати відпочити під накриттям`}},{id:`l3`,text:{en:`Roll and cut`,ua:`Розкачати й нарізати`}}],rightItems:[{id:`r3`,text:{en:`Create even noodle thickness`,ua:`Створити однакову товщину локшини`}},{id:`r2`,text:{en:`Relax dough and prevent drying`,ua:`Розслабити тісто та не дати висохнути`}},{id:`r1`,text:{en:`Form cohesive dough`,ua:`Утворити однорідне тісто`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-110-04`,theoryId:110,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order basic fresh pasta preparation.`,ua:`Упорядкуйте основні етапи приготування свіжої пасти.`},explanation:{en:`Resting improves workability; egg-containing dough requires safe handling.`,ua:`Відпочинок полегшує роботу; яєчне тісто потребує безпечного поводження.`},steps:[{id:`s2`,text:{en:`Wrap and rest dough`,ua:`Загорнути та дати тісту відпочити`}},{id:`s1`,text:{en:`Combine flour and liquid or eggs; knead`,ua:`Змішати борошно з рідиною чи яйцями; замісити`}},{id:`s3`,text:{en:`Roll, cut and cook promptly or store safely`,ua:`Розкачати, нарізати й зварити або безпечно зберегти`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-110-05`,theoryId:110,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which approach is unsafe for fresh egg pasta dough?`,ua:`Який підхід небезпечний для тіста зі свіжими яйцями?`},explanation:{en:`Raw egg and raw flour can carry pathogens; dough should not be tasted uncooked.`,ua:`Сирі яйця й борошно можуть містити патогени; сире тісто куштувати не слід.`},options:[{id:`a`,text:{en:`Keep unused dough appropriately refrigerated`,ua:`Зберігати невикористане тісто належно охолодженим`}},{id:`b`,text:{en:`Clean tools after contact with raw egg`,ua:`Мити інструменти після контакту із сирим яйцем`}},{id:`c`,text:{en:`Taste raw egg-and-flour dough to check seasoning`,ua:`Куштувати сире тісто з яйцем і борошном для перевірки смаку`}}],answer:{optionIds:[`c`]}},{id:`cooking-110-06`,theoryId:110,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which habits help make fresh pasta safely?`,ua:`Які практики допомагають безпечно готувати свіжу пасту?`},explanation:{en:`Raw flour and eggs may contain pathogens.`,ua:`Сирі борошно й яйця можуть містити патогени.`},options:[{id:`a`,text:{en:`Wash hands and utensils after raw egg contact`,ua:`Мити руки й посуд після сирих яєць`}},{id:`b`,text:{en:`Refrigerate egg dough that is not being used promptly`,ua:`Охолоджувати невикористане яєчне тісто без зволікань`}},{id:`c`,text:{en:`Taste raw dough to assess salt`,ua:`Куштувати сире тісто для перевірки солі`}},{id:`d`,text:{en:`Cook dough rather than tasting raw flour`,ua:`Готувати тісто, а не куштувати сире борошно`}}],answer:{optionIds:[`a`,`b`,`d`]}}];var n={theoryId:110,exercises:i};export{n as default,i as exercises,a as theoryId};